from __future__ import annotations

import json
import os
from pathlib import Path

MAGIC = "reshard-v1"
MAX_DIRECTORY_ENTRIES = 30
MAX_FILE_BYTES = 15_000_000
CHUNK_BYTES = 14_000_000
MANIFEST_PART_BYTES = 14_000_000
FANOUT_LEVELS = 6
COPY_BUFFER_BYTES = 1024 * 1024
METADATA_DIR_NAME = ".reshard"
PAYLOAD_DIR_NAME = ".payload"
FORMAT_FILE_NAME = "format.json"
MANIFEST_DIR_NAME = "manifest"


def path_for_index(base: Path, index: int, prefix: str) -> Path:
    if index < 0 or index >= MAX_DIRECTORY_ENTRIES**FANOUT_LEVELS:
        raise ValueError("index is too large for the resharded directory layout")

    digits = [0] * FANOUT_LEVELS
    value = index
    for position in range(FANOUT_LEVELS - 1, -1, -1):
        digits[position] = value % MAX_DIRECTORY_ENTRIES
        value //= MAX_DIRECTORY_ENTRIES

    directory = base
    for digit in digits[:-1]:
        directory /= f"d{digit:02d}"
    return directory / f"{prefix}-{index:012d}"


def json_line(record: dict[str, object]) -> bytes:
    return (
        json.dumps(record, ensure_ascii=True, separators=(",", ":")) + "\n"
    ).encode("ascii")


def validate_relative_path(value: object) -> list[str]:
    if not isinstance(value, str) or not value or "\x00" in value:
        raise ValueError("manifest contains an invalid relative path")
    if value.startswith("/"):
        raise ValueError("manifest contains an absolute path")

    parts = value.split("/")
    if any(part in {"", ".", ".."} for part in parts):
        raise ValueError("manifest contains a path traversal")
    return parts


def lexists(path: Path) -> bool:
    return os.path.lexists(os.fspath(path))


def ensure_parent_directory(root: Path, parts: list[str]) -> Path:
    current = root
    for part in parts:
        current /= part
        if lexists(current):
            if current.is_symlink() or not current.is_dir():
                raise ValueError("manifest path has a non-directory parent")
        else:
            current.mkdir()
    return current


def format_path(root: Path) -> Path:
    return root / METADATA_DIR_NAME / FORMAT_FILE_NAME


def manifest_root(root: Path) -> Path:
    return root / METADATA_DIR_NAME / MANIFEST_DIR_NAME


def payload_root(root: Path) -> Path:
    return root / PAYLOAD_DIR_NAME

from __future__ import annotations

import argparse
import hashlib
import json
import os
import shutil
import stat
import sys
import tempfile
from pathlib import Path

from reshard_common import (
    CHUNK_BYTES,
    COPY_BUFFER_BYTES,
    FANOUT_LEVELS,
    MAGIC,
    MANIFEST_PART_BYTES,
    MAX_DIRECTORY_ENTRIES,
    MAX_FILE_BYTES,
    ensure_parent_directory,
    format_path,
    lexists,
    manifest_root,
    path_for_index,
    payload_root,
    validate_relative_path,
)


def read_format(root: Path) -> dict[str, int | str]:
    path = format_path(root)
    if not path.is_file() or path.is_symlink():
        raise ValueError("resharded directory is missing its format file")
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(f"could not read format file: {error}") from error

    if not isinstance(data, dict) or data.get("magic") != MAGIC:
        raise ValueError("unrecognized resharded directory format")
    expected_values = {
        "version": 1,
        "chunk_bytes": CHUNK_BYTES,
        "max_file_bytes": MAX_FILE_BYTES,
        "fanout": MAX_DIRECTORY_ENTRIES,
        "fanout_levels": FANOUT_LEVELS,
        "manifest_part_bytes": MANIFEST_PART_BYTES,
    }
    for key, expected in expected_values.items():
        if data.get(key) != expected:
            raise ValueError(f"unsupported or invalid format value: {key}")

    for key in ("manifest_parts", "entry_count", "chunk_count", "root_mode"):
        value = data.get(key)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ValueError(f"invalid format value: {key}")

    if data["manifest_parts"] > MAX_DIRECTORY_ENTRIES**FANOUT_LEVELS:
        raise ValueError("manifest has too many parts")
    if data["chunk_count"] > MAX_DIRECTORY_ENTRIES**FANOUT_LEVELS:
        raise ValueError("payload has too many chunks")
    if data["root_mode"] & ~0o7777:
        raise ValueError("invalid root directory mode")
    return data


def assert_new_path(path: Path) -> None:
    if lexists(path):
        raise ValueError(f"manifest contains a duplicate path: {path}")


def validate_mode(value: object) -> int:
    if not isinstance(value, int) or isinstance(value, bool) or value < 0 or value > 0o7777:
        raise ValueError("manifest contains an invalid mode")
    return value


def validate_nonnegative_integer(value: object, field: str) -> int:
    if not isinstance(value, int) or isinstance(value, bool) or value < 0:
        raise ValueError(f"manifest contains an invalid {field}")
    return value


def copy_one_file(
    root: Path,
    destination: Path,
    size: int,
    first_chunk: int,
    number_of_chunks: int,
) -> str:
    digest = hashlib.sha256()
    remaining = size

    with destination.open("xb") as output:
        for offset in range(number_of_chunks):
            current_size = min(CHUNK_BYTES, remaining)
            chunk_path = path_for_index(
                payload_root(root), first_chunk + offset, "chunk"
            )
            if (
                chunk_path.is_symlink()
                or not chunk_path.is_file()
                or chunk_path.stat().st_size != current_size
            ):
                raise ValueError(f"missing or invalid payload chunk: {chunk_path}")

            written = 0
            with chunk_path.open("rb") as chunk:
                while written < current_size:
                    data = chunk.read(min(COPY_BUFFER_BYTES, current_size - written))
                    if not data:
                        raise ValueError(f"truncated payload chunk: {chunk_path}")
                    output.write(data)
                    digest.update(data)
                    written += len(data)
                if chunk.read(1):
                    raise ValueError(f"oversized payload chunk: {chunk_path}")
            remaining -= current_size

    if remaining != 0:
        raise ValueError("file size does not match its payload chunks")
    return digest.hexdigest()


def restore_entries(root: Path, temporary_root: Path, format_data: dict[str, int | str]) -> None:
    metadata = manifest_root(root)
    if not metadata.is_dir() or metadata.is_symlink():
        raise ValueError("resharded directory is missing its manifest directory")

    seen: dict[str, str] = {}
    directory_modes: list[tuple[Path, int]] = []
    file_modes: list[tuple[Path, int]] = []
    next_chunk = 0
    entry_count = 0

    for part_number in range(format_data["manifest_parts"]):
        part_path = path_for_index(metadata, part_number, "part")
        if part_path.is_symlink() or not part_path.is_file():
            raise ValueError(f"missing manifest part: {part_path}")

        try:
            lines = part_path.open("r", encoding="utf-8")
        except OSError as error:
            raise ValueError(f"could not read manifest part: {error}") from error
        with lines:
            for line_number, line in enumerate(lines, start=1):
                if not line.strip():
                    raise ValueError(
                        f"empty manifest line in {part_path}:{line_number}"
                    )
                try:
                    record = json.loads(line)
                except json.JSONDecodeError as error:
                    raise ValueError(
                        f"invalid manifest JSON in {part_path}:{line_number}"
                    ) from error
                if not isinstance(record, dict):
                    raise ValueError("manifest record is not an object")

                parts = validate_relative_path(record.get("p"))
                relative = "/".join(parts)
                if relative in seen:
                    raise ValueError(f"manifest contains a duplicate path: {relative}")
                parent_parts = parts[:-1]
                for index in range(1, len(parts)):
                    parent = "/".join(parts[:index])
                    if seen.get(parent) != "d":
                        raise ValueError(
                            f"manifest entry has no directory parent: {relative}"
                        )

                destination = temporary_root.joinpath(*parts)
                ensure_parent_directory(temporary_root, parent_parts)
                assert_new_path(destination)
                entry_type = record.get("t")

                if entry_type == "d":
                    mode = validate_mode(record.get("m"))
                    destination.mkdir()
                    seen[relative] = "d"
                    directory_modes.append((destination, mode))
                elif entry_type == "l":
                    target = record.get("v")
                    if not isinstance(target, str) or "\x00" in target:
                        raise ValueError("manifest contains an invalid symlink target")
                    os.symlink(target, destination)
                    seen[relative] = "l"
                elif entry_type == "f":
                    mode = validate_mode(record.get("m"))
                    size = validate_nonnegative_integer(record.get("s"), "file size")
                    first_chunk = validate_nonnegative_integer(
                        record.get("c"), "chunk index"
                    )
                    number_of_chunks = validate_nonnegative_integer(
                        record.get("n"), "chunk count"
                    )
                    digest = record.get("h")
                    if (
                        not isinstance(digest, str)
                        or len(digest) != 64
                        or any(character not in "0123456789abcdef" for character in digest)
                    ):
                        raise ValueError("manifest contains an invalid file checksum")
                    expected_chunks = (size + CHUNK_BYTES - 1) // CHUNK_BYTES
                    if number_of_chunks != expected_chunks or first_chunk != next_chunk:
                        raise ValueError("manifest chunk sequence is invalid")
                    actual_digest = copy_one_file(
                        root,
                        destination,
                        size,
                        first_chunk,
                        number_of_chunks,
                    )
                    if actual_digest != digest:
                        raise ValueError(f"checksum mismatch for {relative}")
                    seen[relative] = "f"
                    file_modes.append((destination, mode))
                    next_chunk += number_of_chunks
                else:
                    raise ValueError(f"manifest contains an invalid entry type: {entry_type}")
                entry_count += 1

    if entry_count != format_data["entry_count"]:
        raise ValueError("manifest entry count does not match the format file")
    if next_chunk != format_data["chunk_count"]:
        raise ValueError("manifest chunk count does not match the format file")

    for path, mode in file_modes:
        os.chmod(path, mode)
    for path, mode in sorted(
        directory_modes, key=lambda item: len(item[0].parts), reverse=True
    ):
        os.chmod(path, mode)
    os.chmod(temporary_root, format_data["root_mode"])


def replace_with_restored(root: Path, temporary_root: Path) -> None:
    backup = Path(
        tempfile.mkdtemp(prefix=f".{root.name}.backup-", dir=root.parent)
    )
    shutil.rmtree(backup)
    try:
        os.replace(root, backup)
        os.replace(temporary_root, root)
    except Exception:
        if not lexists(root) and lexists(backup):
            os.replace(backup, root)
        if lexists(temporary_root):
            shutil.rmtree(temporary_root)
        raise
    shutil.rmtree(backup)


def decompress(resharded_path: str) -> None:
    requested_root = Path(resharded_path).expanduser()
    if requested_root.is_symlink() or not requested_root.is_dir():
        raise ValueError("resharded path must be a directory and not a symbolic link")
    root = requested_root.resolve()
    format_data = read_format(root)

    temporary_root = Path(
        tempfile.mkdtemp(prefix=f".{root.name}.restore-", dir=root.parent)
    )
    try:
        restore_entries(root, temporary_root, format_data)
        replace_with_restored(root, temporary_root)
    except Exception:
        if lexists(temporary_root):
            shutil.rmtree(temporary_root)
        raise
    print(f"Restored {format_data['entry_count']} entries in place at {root}")


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Restore a directory produced by compress.py in place."
    )
    parser.add_argument("resharded_dir")
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        decompress(args.resharded_dir)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        print(f"decompress.py: error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

