from __future__ import annotations

import argparse
import hashlib
import json
import os
import shutil
import stat
import sys
from dataclasses import dataclass
from pathlib import Path

from reshard_common import (
    CHUNK_BYTES,
    COPY_BUFFER_BYTES,
    FANOUT_LEVELS,
    MAGIC,
    MANIFEST_PART_BYTES,
    MAX_DIRECTORY_ENTRIES,
    MAX_FILE_BYTES,
    PAYLOAD_DIR_NAME,
    format_path,
    json_line,
    manifest_root,
    path_for_index,
    payload_root,
)


@dataclass(frozen=True)
class InputEntry:
    source: Path
    relative_path: str
    kind: str
    mode: int
    size: int = 0
    symlink_target: str | None = None


class ManifestWriter:
    def __init__(self, output_dir: Path) -> None:
        self.root = manifest_root(output_dir)
        self.root.mkdir(parents=True, exist_ok=True)
        self.part_file = None
        self.part_bytes = 0
        self.part_count = 0

    def write(self, record: dict[str, object]) -> None:
        line = json_line(record)
        if len(line) > MANIFEST_PART_BYTES:
            raise ValueError("a manifest record is larger than the maximum file size")

        if self.part_file is None or self.part_bytes + len(line) > MANIFEST_PART_BYTES:
            self.close_part()
            part_path = path_for_index(self.root, self.part_count, "part")
            part_path.parent.mkdir(parents=True, exist_ok=True)
            self.part_file = part_path.open("wb")
            self.part_bytes = 0
            self.part_count += 1

        self.part_file.write(line)
        self.part_bytes += len(line)

    def close_part(self) -> None:
        if self.part_file is not None:
            self.part_file.close()
            self.part_file = None
            self.part_bytes = 0

    def close(self) -> None:
        self.close_part()


def collect_entries(root: Path) -> list[InputEntry]:
    entries: list[InputEntry] = []

    def visit(directory: Path, parent_parts: tuple[str, ...]) -> None:
        with os.scandir(directory) as scanner:
            children = sorted(scanner, key=lambda entry: entry.name)

        for child in children:
            relative_parts = parent_parts + (child.name,)
            relative_path = "/".join(relative_parts)
            child_path = Path(child.path)
            child_stat = child.stat(follow_symlinks=False)
            mode = stat.S_IMODE(child_stat.st_mode)

            if child.is_symlink():
                entries.append(
                    InputEntry(
                        source=child_path,
                        relative_path=relative_path,
                        kind="l",
                        mode=mode,
                        symlink_target=os.readlink(child_path),
                    )
                )
            elif child.is_dir(follow_symlinks=False):
                entries.append(
                    InputEntry(
                        source=child_path,
                        relative_path=relative_path,
                        kind="d",
                        mode=mode,
                    )
                )
                visit(child_path, relative_parts)
            elif child.is_file(follow_symlinks=False):
                entries.append(
                    InputEntry(
                        source=child_path,
                        relative_path=relative_path,
                        kind="f",
                        mode=mode,
                        size=child_stat.st_size,
                    )
                )
            else:
                raise ValueError(f"unsupported input entry type: {child_path}")

    visit(root, ())
    return entries


def chunk_count(size: int) -> int:
    return (size + CHUNK_BYTES - 1) // CHUNK_BYTES


def copy_file_chunks(
    entry: InputEntry, output_dir: Path, first_chunk: int, expected_chunks: int
) -> str:
    digest = hashlib.sha256()
    remaining_file = entry.size

    with entry.source.open("rb") as source:
        for offset in range(expected_chunks):
            current_size = min(CHUNK_BYTES, remaining_file)
            chunk_path = path_for_index(
                payload_root(output_dir), first_chunk + offset, "chunk"
            )
            chunk_path.parent.mkdir(parents=True, exist_ok=True)

            written = 0
            with chunk_path.open("wb") as chunk:
                while written < current_size:
                    data = source.read(
                        min(COPY_BUFFER_BYTES, current_size - written)
                    )
                    if not data:
                        raise ValueError(
                            f"input file changed while reading: {entry.source}"
                        )
                    chunk.write(data)
                    digest.update(data)
                    written += len(data)

            if chunk_path.stat().st_size != current_size:
                raise OSError(f"could not write complete chunk: {chunk_path}")
            remaining_file -= current_size

        if remaining_file != 0 or source.read(1):
            raise ValueError(f"input file changed while reading: {entry.source}")

    return digest.hexdigest()


def prepare_output(input_dir: Path, requested_output: Path) -> tuple[Path, bool]:
    output_dir = requested_output.expanduser()
    output_resolved = output_dir.resolve()

    if output_resolved == input_dir or input_dir in output_resolved.parents:
        raise ValueError("output directory must not be the input directory or its child")

    existed = output_dir.exists() or output_dir.is_symlink()
    if output_dir.is_symlink():
        raise ValueError("output directory must not be a symbolic link")
    if existed and not output_dir.is_dir():
        raise ValueError("output path is not a directory")
    if existed and any(output_dir.iterdir()):
        raise ValueError("output directory must be new or empty")
    if not existed:
        output_dir.mkdir(parents=True, exist_ok=False)

    return output_dir.resolve(), not existed


def compress(input_path: str, output_path: str) -> None:
    requested_input = Path(input_path).expanduser()
    if requested_input.is_symlink() or not requested_input.is_dir():
        raise ValueError("input path must be a directory and not a symbolic link")
    input_dir = requested_input.resolve()

    output_dir, created_output = prepare_output(input_dir, Path(output_path))
    succeeded = False
    try:
        entries = collect_entries(input_dir)
        total_chunks = sum(
            chunk_count(entry.size) for entry in entries if entry.kind == "f"
        )
        if total_chunks >= MAX_DIRECTORY_ENTRIES**FANOUT_LEVELS:
            raise ValueError("input contains too many chunks for the output layout")

        metadata_dir = output_dir / ".reshard"
        metadata_dir.mkdir(parents=True, exist_ok=True)
        payload_root(output_dir).mkdir(parents=True, exist_ok=True)
        writer = ManifestWriter(output_dir)
        next_chunk = 0

        try:
            for entry in entries:
                if entry.kind == "d":
                    writer.write(
                        {"p": entry.relative_path, "t": "d", "m": entry.mode}
                    )
                elif entry.kind == "l":
                    writer.write(
                        {
                            "p": entry.relative_path,
                            "t": "l",
                            "v": entry.symlink_target,
                        }
                    )
                else:
                    number_of_chunks = chunk_count(entry.size)
                    digest = copy_file_chunks(
                        entry, output_dir, next_chunk, number_of_chunks
                    )
                    writer.write(
                        {
                            "p": entry.relative_path,
                            "t": "f",
                            "m": entry.mode,
                            "s": entry.size,
                            "c": next_chunk,
                            "n": number_of_chunks,
                            "h": digest,
                        }
                    )
                    next_chunk += number_of_chunks
        finally:
            writer.close()

        if next_chunk != total_chunks:
            raise AssertionError("internal chunk count mismatch")

        format_data = {
            "magic": MAGIC,
            "version": 1,
            "chunk_bytes": CHUNK_BYTES,
            "max_file_bytes": MAX_FILE_BYTES,
            "fanout": MAX_DIRECTORY_ENTRIES,
            "fanout_levels": FANOUT_LEVELS,
            "manifest_part_bytes": MANIFEST_PART_BYTES,
            "manifest_parts": writer.part_count,
            "entry_count": len(entries),
            "chunk_count": total_chunks,
            "root_mode": stat.S_IMODE(input_dir.stat().st_mode),
        }
        format_path(output_dir).write_text(
            json.dumps(format_data, ensure_ascii=True, separators=(",", ":")),
            encoding="utf-8",
        )
        succeeded = True
        print(
            f"Resharded {len(entries)} entries into {total_chunks} chunks at {output_dir}"
        )
    finally:
        if not succeeded and created_output and output_dir.exists():
            shutil.rmtree(output_dir)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Reshard a directory into a reversible 30-way layout."
    )
    parser.add_argument("input_dir")
    parser.add_argument("output_dir")
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        compress(args.input_dir, args.output_dir)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        print(f"compress.py: error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

